omega_invalidate_stale_translations():
CREATE OR REPLACE FUNCTION public.omega_invalidate_stale_translations()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
    BEGIN
        -- Si el contenido ha mutado, purgamos las traducciones cacheadas
        IF OLD.content IS DISTINCT FROM NEW.content THEN
            DELETE FROM public.post_translations WHERE post_id = NEW.uuid;
            RAISE USING MESSAGE = 'Traducciones eliminadas para el post mutado: ' || NEW.uuid;
        END IF;
        RETURN NEW;
    END;
    $function$

omega_set_default_parent_id():
CREATE OR REPLACE FUNCTION public.omega_set_default_parent_id()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
    BEGIN
        IF NEW.parent_id IS NULL THEN
            NEW.parent_id := NEW.id;
        END IF;
        RETURN NEW;
    END;
    $function$
